Create a to-do app com base no seguinte prompt "<!DOCTYPE html>
<html lang="pt-BR">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Oráculo do Tarô - Arcanos Maiores</title>
    <style>
        :root {
            --bg-color: #121214;
            --card-bg: #202024;
            --text-color: #e1e1e6;
            --accent-color: #8257e5;
            --accent-hover: #9466ff;
            --border-color: #29292e;
        }

        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            background-color: var(--bg-color);
            color: var(--text-color);
            margin: 0;
            padding: 20px;
            display: flex;
            flex-direction: column;
            align-items: center;
            min-height: 100vh;
        }

        header {
            text-align: center;
            margin-bottom: 30px;
        }

        h1 {
            color: var(--accent-color);
            margin-bottom: 10px;
        }

        .container {
            width: 100%;
            max-width: 900px;
            background: var(--card-bg);
            padding: 30px;
            border-radius: 12px;
            box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
            border: 1px solid var(--border-color);
        }

        .form-group {
            margin-bottom: 20px;
        }

        label {
            display: block;
            margin-bottom: 8px;
            font-weight: 600;
        }

        select, input, button {
            width: 100%;
            padding: 12px;
            border-radius: 8px;
            border: 1px solid var(--border-color);
            background: #121214;
            color: var(--text-color);
            font-size: 1rem;
            box-sizing: border-box;
        }

        button {
            background-color: var(--accent-color);
            color: white;
            border: none;
            font-weight: bold;
            cursor: pointer;
            transition: background 0.2s;
            margin-top: 10px;
        }

        button:hover {
            background-color: var(--accent-hover);
        }

        .spread-results {
            display: flex;
            flex-wrap: wrap;
            gap: 15px;
            justify-content: center;
            margin-top: 30px;
        }

        .card-slot {
            background: #121214;
            border: 2px solid var(--border-color);
            border-radius: 8px;
            padding: 15px;
            width: 160px;
            min-height: 220px;
            display: flex;
            flex-direction: column;
            align-items: center;
            text-align: center;
            position: relative;
        }

        .card-slot h4 {
            margin: 0 0 10px 0;
            color: var(--accent-color);
            font-size: 0.9rem;
        }

        .card-name {
            font-weight: bold;
            margin-top: 10px;
            font-size: 0.95rem;
        }

        .card-orientation {
            font-size: 0.8rem;
            color: #a0a0a0;
            margin-top: 4px;
        }

        .card-desc {
            font-size: 0.75rem;
            margin-top: 8px;
            text-align: left;
            color: #c4c4cc;
        }

        .reversed {
            color: #f75a68;
        }
    </style>
</head>
<body>

    <header>
        <h1>Oráculo dos Arcanos Maiores</h1>
        <p>Estudo simbólico, espiritual e tiragens baseadas no Informativo Iniciático[span_2](start_span)[span_2](end_span)</p>
    </header>

    <div class="container">
        <div class="form-group">
            <label for="question">Qual a sua pergunta ou foco para a consulta?</label>
            <input type="text" id="question" placeholder="Ex: O que preciso compreender sobre meu momento atual?">
        </div>

        <div class="form-group">
            <label for="spreadType">Escolha o Método de Tiragem:</label>
            <select id="spreadType">
                <option value="5">Método de 5 Cartas (Raiz, Momento, Obstáculo, Conselho, Arcano Chave)</option>
                <option value="3">Método de 3 Cartas (Situação, Atenção, Orientação)</option>
                <option value="1">Arcano do Dia (1 Carta)</option>
            </select>
        </div>

        <button onclick="realizarTiragem()">Realizar Tiragem</button>

        <div id="results" class="spread-results"></div>
    </div>

    <script>
        const arcanos = [
            { id: 0, nome: "O Mago", direito: "Habilidade, iniciativa, escolha antes de agir.", invertido: "Disputas, ação mal orientada, dispersão." },
            { id: 1, nome: "A Papisa", direito: "Revelação, meditação, situação segura.", invertido: "Intuições falsas, atraso, lentidão." },
            { id: 2, nome: "A Imperatriz", direito: "Pensamento fecundo, soluções, melhora.", invertido: "Divergências, complicação, atraso." },
            { id: 3, nome: "O Imperador", direito: "Realização, acordo, contrato, situação definida.", invertido: "Ruptura de equilíbrio, risco de perdas." },
            { id: 4, nome: "O Papa", direito: "Conselho sólido, segurança, vocação.", invertido: "Falta de apoio espiritual, projeto retardado." },
            { id: 5, nome: "O Enamorado", direito: "União, escolha a fazer.", invertido: "Desordem, cisão, risco de ruptura." },
            { id: 6, nome: "A Carruagem", direito: "Atividade, rapidez, conquista, notícia boa.", invertido: "Desordem, imprudência, más notícias." },
            { id: 7, nome: "A Justiça", direito: "Julgamento claro, rigor, justiça feita.", invertido: "Risco de perda ou de julgamento injusto." },
            { id: 8, nome: "O Eremita", direito: "Luz sobre um problema, prudência, segredo.", invertido: "Obscuridade, visão falsa da situação." },
            { id: 9, nome: "Roda da Fortuna", direito: "Mudança, evolução, julgamento equilibrado.", invertido: "Transformação lenta e difícil." },
            { id: 10, nome: "A Força", direito: "Domínio de si, firmeza, poder de dirigir.", invertido: "Brutalidade ou fraqueza, risco de ser dominado." },
            { id: 11, nome: "O Dependurado", direito: "Espera, renúncia, indecisão.", invertido: "Éxito incerto, reticência, projeto secreto." },
            { id: 12, nome: "A Morte (Sem Nome)", direito: "Renovação, fim de etapa, mudança total.", invertido: "Estagnação, mudança adiada." },
            { id: 13, nome: "A Temperança", direito: "Conciliação, adaptação, decisão sem pressa.", invertido: "Perturbação, discordância." },
            { id: 14, nome: "O Diabo", direito: "Éxito material, influência, advertência.", invertido: "Desordem, negócios escusos." },
            { id: 15, nome: "A Torre", direito: "Interrupção brusca, choque, advertência.", invertido: "Grande abalo, confusão." },
            { id: 16, nome: "A Estrela", direito: "Inspiração, esperança, harmonia.", invertido: "Harmonia rompida ou sem duração." },
            { id: 17, nome: "A Lua", direito: "Engano, confusão, segredo desvendado.", invertido: "Instinto acentuado, confusão latente." },
            { id: 18, nome: "O Sol", direito: "Sucesso, clareza, vitalidade, afeto altruísta.", invertido: "Contrariedade, tatear no escuro." },
            { id: 19, nome: "O Julgamento", direito: "Despertar, avaliação, estabilidade.", invertido: "Erro a respeito de si mesmo." },
            { id: 20, nome: "O Mundo", direito: "Realização, elevação, sucesso.", invertido: "Ciladas, insucesso, triunfo negado." },
            { id: 21, nome: "O Louco", direito: "Partida, mudança, despreocupação.", invertido: "Queda, interrupção, confusão." }
        ];

        function embaralhar(array) {
            let currentIndex = array.length, randomIndex;
            while (currentIndex != 0) {
                randomIndex = Math.floor(Math.random() * currentIndex);
                currentIndex--;
                [array[currentIndex], array[randomIndex]] = [array[randomIndex], array[currentIndex]];
            }
            return array;
        }

        function realizarTiragem() {
            const pergunta = document.getElementById('question').value;
            const tipoTiragem = document.getElementById('spreadType').value;
            const resultadosDiv = document.getElementById('results');

            resultadosDiv.innerHTML = '';

            if (!pergunta.trim()) {
                alert('Por favor, insira uma pergunta ou foco para a consulta.');
                return;
            }

            // Cópia e embaralhamento dos arcanos
            let baralho = [...arcanos];
            embaralhar(baralho);

            let posicoesNames = [];
            if (tipoTiragem === '5') {
                posicoesNames = ["1. Raiz", "2. Momento", "3. Obstáculo", "4. Conselho", "5. Arcano Chave"];
            } else if (tipoTiragem === '3') {
                posicoesNames = ["1. A Situação", "2. O que pede atenção", "3. A Orientação"];
            } else {
                posicoesNames = ["Arcano do Dia"];
            }

            posicoesNames.forEach((nomePosicao, index) => {
                const carta = baralho[index];
                const invertida = Math.random() < 0.25; // 25% de chance de sair invertida para simular a prática real

                const slot = document.createElement('div');
                slot.className = 'card-slot';

                slot.innerHTML = `
                    <h4>${nomePosicao}</h4>
                    <div class="card-name">${carta.nome}</div>
                    <div class="card-orientation ${invertida ? 'inverted' : ''}">
                        ${invertida ? 'Invertida' : 'Direita'}
                    </div>
                    <div class="card-desc">
                        ${invertida ? carta.invertido : carta.direito}
                    </div>
                `;
                resultadosDiv.appendChild(slot);
            });
        }
    </script>
</body>
</html>
"

E aprimore ele melhorando a interface e usabilidade. Também quero que o app possa ficar disponível e acessível pelo navegador.
